core::Finding policy_profile_0(const Item&it){core::Severity s=core::Severity::Info;std::string d="Policy item profile accepted";for(auto&v:it.values){if(it.key.find("network")!=std::string::npos&&!core::parse_cidr(v)){s=core::Severity::Medium;d="Network value did not parse as CIDR";}if(it.key.find("domain")!=std::string::npos&&!core::domain_like(v)){s=core::Severity::Low;d="Domain value did not match expected shape";}}return{s,"policy-profile","Policy profile 0",d,it.loc,it.values};}
bool policy_key_profile_0(const Item&it){auto k=core::lower(it.key);return k.find("allowed")!=std::string::npos||k.find("blocked")!=std::string::npos||it.values.size()>0;}
